// Filtrerer opskrifter i grafen ud fra hårde krav
const input = $('Start').first().json;
const toList = v => (Array.isArray(v) ? v : String(v || '').split(','))
  .map(s => String(s).trim().toLowerCase()).filter(Boolean);
const maxTime = Number(input.maxTime) > 0 ? Math.round(Number(input.maxTime)) : null;
const tag = input.tag ? String(input.tag).trim().toLowerCase() : null;
const category = input.category ? String(input.category).trim() : null;
const parameters = {
  mustHave: toList(input.mustHave),
  exclude: toList(input.exclude),
  tag, maxTime, category, limit: 10
};
const statement = [
  "MATCH (r:Recipe)",
  "WHERE ($maxTime IS NULL OR (r.totalTime IS NOT NULL AND r.totalTime <= $maxTime))",
  "AND all(m IN $mustHave WHERE EXISTS { MATCH (r)-[:HAS_INGREDIENT]->(i:Ingredient) WHERE i.name CONTAINS m })",
  "AND none(x IN $exclude WHERE EXISTS { MATCH (r)-[:HAS_INGREDIENT]->(i:Ingredient) WHERE i.name CONTAINS x })",
  "AND ($tag IS NULL OR EXISTS { MATCH (r)-[:HAS_TAG]->(t:Tag) WHERE t.name CONTAINS $tag })",
  "AND ($category IS NULL OR EXISTS { MATCH (r)-[:IN_CATEGORY]->(c:Category) WHERE toLower(c.name) CONTAINS toLower($category) })",
  "OPTIONAL MATCH (r)-[:IN_CATEGORY]->(cat:Category)",
  "RETURN r.id AS recipeId, r.name AS name, r.totalTime AS minutes, r.rating AS rating, cat.name AS category,",
  "  [(r)-[:HAS_INGREDIENT]->(i) | i.name] AS ingredients,",
  "  [(r)-[:HAS_TAG]->(t) | t.name] AS tags,",
  "  'Neo4j graph (Food.com RecipeId ' + r.id + ')' AS source",
  "ORDER BY coalesce(r.rating, 0) DESC",
  "LIMIT $limit"
].join(' ');
return [{ json: { statements: [{ statement, parameters }] } }];

// Laver Neo4j's svar om til en læsbar liste til agenten
const res = $input.first().json;
if (res.errors && res.errors.length) {
  return [{ json: { error: res.errors.map(e => e.message).join('; ') } }];
}
const r = res.results[0];
const rows = r.data.map(d => Object.fromEntries(r.columns.map((c, i) => [c, d.row[i]])));
return [{ json: { count: rows.length, results: rows } }];
